create table app_auth."user" (id text primary key, name text not null, email text not null unique, "emailVerified" boolean not null default false, image text, "createdAt" timestamptz not null default now(), "updatedAt" timestamptz not null default now());
create table app_auth.session (id text primary key, "expiresAt" timestamptz not null, token text not null unique, "createdAt" timestamptz not null default now(), "updatedAt" timestamptz not null default now(), "ipAddress" text, "userAgent" text, "userId" text not null references app_auth."user"(id) on delete cascade);
create table app_auth.account (id text primary key, "accountId" text not null, "providerId" text not null, "userId" text not null references app_auth."user"(id) on delete cascade, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, scope text, password text, "createdAt" timestamptz not null default now(), "updatedAt" timestamptz not null default now());
create table app_auth.verification (id text primary key, identifier text not null, value text not null, "expiresAt" timestamptz not null, "createdAt" timestamptz not null default now(), "updatedAt" timestamptz not null default now());
create index auth_session_user on app_auth.session("userId"); create index auth_account_user on app_auth.account("userId"); create index auth_verification_identifier on app_auth.verification(identifier);
revoke all on schema app,app_auth from public;
